deps = {
    "book_venue": [],
    "send_invites": ["book_venue"],
    "order_food": ["book_venue"],
    "confirm_speaker": [],
    "print_programs": ["confirm_speaker", "send_invites"],
    "run_event": ["send_invites", "order_food", "print_programs"],
}
proposed = ["book_venue", "print_programs", "send_invites", "confirm_speaker", "order_food", "run_event"]
pos = {step: i for i, step in enumerate(proposed)}
violations = []
for step, needs in deps.items():
    for n in needs:
        if pos[n] > pos[step]:
            violations.append(f"{step} is scheduled before {n}, which it depends on")
print("steps checked:", len(proposed))
print("violations found:", len(violations))
for v in violations:
    print("VIOLATION:", v)

budget_cap = 3000
plan_cost = {"venue": 1200, "catering": 950, "kit": 420, "printing": 260, "staff_overtime": 240}
deadline_day = 10
task_days = {"book": 1, "design": 3, "print": 2, "deliver": 1, "setup": 1}
caps = {"lead": 24, "tech": 30}
hours = {"lead": 26, "tech": 28}
def verify(cost, hours):
    problems = []
    total = sum(cost.values())
    if total > budget_cap:
        problems.append(f"budget: {total} over cap by {total - budget_cap}")
    span = sum(task_days.values())
    if span > deadline_day:
        problems.append(f"deadline: chain takes {span} days, limit {deadline_day}")
    for p in caps:
        if hours[p] > caps[p]:
            problems.append(f"staffing: {p} at {hours[p]}h over cap {caps[p]}h")
    return problems
print("as proposed:")
for p in verify(plan_cost, hours):
    print(" -", p)
plan_cost["printing"] = 150
hours["lead"] = 24
print("after repair (printing renegotiated to 150, 2 lead hours moved to a freelancer outside the cap):")
print(" problems:", verify(plan_cost, hours) or "none")
print(" repaired total:", sum(plan_cost.values()))

topics = {  # topic: (past-paper score %, sessions wanted max)
    "algebra": (82, 4),
    "geometry": (45, 6),
    "trigonometry": (58, 6),
    "probability": (71, 4),
    "calculus": (34, 6),
}
sessions_available = 20
weights = {t: (100 - score) for t, (score, cap) in topics.items()}
total_weight = sum(weights.values())
alloc = {}
for t, w in weights.items():
    alloc[t] = min(topics[t][1], round(sessions_available * w / total_weight))
while sum(alloc.values()) > sessions_available:
    t = max(alloc, key=lambda x: alloc[x] - 1)
    alloc[t] -= 1
while sum(alloc.values()) < sessions_available:
    candidates = [t for t in alloc if alloc[t] < topics[t][1]]
    t = max(candidates, key=lambda x: weights[x])
    alloc[t] += 1
for t in sorted(alloc, key=lambda x: weights[x], reverse=True):
    print(f"{t}: score {topics[t][0]}%, sessions {alloc[t]}")
print("total sessions:", sum(alloc.values()), "of", sessions_available)
